PRAGMA foreign_keys=ON;
CREATE TABLE dim_localizacao(localizacao_id INTEGER PRIMARY KEY,bairro TEXT NOT NULL,cidade TEXT NOT NULL,uf TEXT NOT NULL,zona TEXT NOT NULL,preco_m2_referencia REAL NOT NULL,indice_valorizacao REAL NOT NULL);
CREATE TABLE dim_tipo_imovel(tipo_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,segmento TEXT NOT NULL);
CREATE TABLE dim_proprietario(proprietario_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,tipo_pessoa TEXT NOT NULL,perfil_investidor TEXT NOT NULL);
CREATE TABLE dim_cliente(cliente_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,perfil TEXT NOT NULL,faixa_orcamento TEXT NOT NULL,interesse TEXT NOT NULL,cidade_preferida TEXT NOT NULL);
CREATE TABLE fato_imovel(imovel_id INTEGER PRIMARY KEY,codigo TEXT NOT NULL UNIQUE,proprietario_id INTEGER NOT NULL,localizacao_id INTEGER NOT NULL,tipo_id INTEGER NOT NULL,area_m2 REAL NOT NULL,quartos INTEGER NOT NULL,banheiros INTEGER NOT NULL,vagas INTEGER NOT NULL,idade_anos INTEGER NOT NULL,perfil TEXT NOT NULL,status TEXT NOT NULL,valor_estimado REAL NOT NULL,aluguel_estimado REAL NOT NULL,estado_conservacao TEXT NOT NULL,mobiliado INTEGER NOT NULL,FOREIGN KEY(proprietario_id) REFERENCES dim_proprietario(proprietario_id),FOREIGN KEY(localizacao_id) REFERENCES dim_localizacao(localizacao_id),FOREIGN KEY(tipo_id) REFERENCES dim_tipo_imovel(tipo_id));
CREATE TABLE fato_historico_preco(historico_id INTEGER PRIMARY KEY,imovel_id INTEGER NOT NULL,competencia TEXT NOT NULL,valor_estimado REAL NOT NULL,preco_m2 REAL NOT NULL,fonte TEXT NOT NULL,FOREIGN KEY(imovel_id) REFERENCES fato_imovel(imovel_id));
CREATE TABLE fato_anuncio(anuncio_id INTEGER PRIMARY KEY,imovel_id INTEGER NOT NULL,finalidade TEXT NOT NULL,data_inicio TEXT NOT NULL,data_fim TEXT,preco_anunciado REAL NOT NULL,status TEXT NOT NULL,canal TEXT NOT NULL,visualizacoes INTEGER NOT NULL,leads INTEGER NOT NULL,FOREIGN KEY(imovel_id) REFERENCES fato_imovel(imovel_id));
CREATE TABLE fato_contrato_aluguel(contrato_id INTEGER PRIMARY KEY,imovel_id INTEGER NOT NULL,cliente_id INTEGER NOT NULL,data_inicio TEXT NOT NULL,data_fim_prevista TEXT NOT NULL,data_fim_real TEXT,valor_aluguel REAL NOT NULL,indice_reajuste TEXT NOT NULL,deposito_garantia REAL NOT NULL,status TEXT NOT NULL,FOREIGN KEY(imovel_id) REFERENCES fato_imovel(imovel_id),FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id));
CREATE TABLE fato_vacancia(vacancia_id INTEGER PRIMARY KEY,imovel_id INTEGER NOT NULL,data_inicio TEXT NOT NULL,data_fim TEXT,dias_vago INTEGER NOT NULL,motivo TEXT NOT NULL,FOREIGN KEY(imovel_id) REFERENCES fato_imovel(imovel_id));
CREATE TABLE fato_transacao(transacao_id INTEGER PRIMARY KEY,imovel_id INTEGER NOT NULL,cliente_id INTEGER NOT NULL,data_venda TEXT NOT NULL,preco_pedido REAL NOT NULL,preco_venda REAL NOT NULL,desconto_pct REAL NOT NULL,dias_mercado INTEGER NOT NULL,forma_pagamento TEXT NOT NULL,FOREIGN KEY(imovel_id) REFERENCES fato_imovel(imovel_id),FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id));
CREATE TABLE fato_proposta(proposta_id INTEGER PRIMARY KEY,anuncio_id INTEGER NOT NULL,cliente_id INTEGER NOT NULL,data_proposta TEXT NOT NULL,valor_proposta REAL NOT NULL,status TEXT NOT NULL,condicao_principal TEXT NOT NULL,FOREIGN KEY(anuncio_id) REFERENCES fato_anuncio(anuncio_id),FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id));
CREATE INDEX idx_preco_competencia ON fato_historico_preco(competencia);CREATE INDEX idx_imovel_localizacao ON fato_imovel(localizacao_id);CREATE INDEX idx_contrato_status ON fato_contrato_aluguel(status);CREATE INDEX idx_vacancia_imovel ON fato_vacancia(imovel_id);
